export function makeBoard(title) {
  return {
    title,
    scores: {},
    add(player, points) {
      this.scores[player] = (this.scores[player] ?? 0) + points;
    },
    report() {
      function line(player) {
        return `${this.title}: ${player} ${this.scores[player]}`;
      }

      return Object.keys(this.scores).map(line);
    },
  };
}
